-- Catálogo de conquistas do Futeiros (D112). Gerado por `pnpm supabase:catalogo`
-- a partir de @craque/content: não edite à mão. Uma conquista nova no jogo pede
-- uma migração nova deste tipo (o teste do pacote @craque/supabase avisa).

on conflict (id) do update set
  jogo = excluded.jogo,
  grupo = excluded.grupo,
  raridade = excluded.raridade,
  secreta = excluded.secreta,
  alvo = excluded.alvo,
  nome = excluded.nome,
  descricao = excluded.descricao,
  ordem = excluded.ordem,
  ativa = true;

update public.conquistas set ativa = false
where id <> all (array['record:careerGoals', 'record:ballonDor', 'record:worldCups', 'record:seasonGoals', 'record:careerTitles', 'record:goldenShoes', 'record:internationalGoals', 'record:caps', 'record:careerGames', 'record:championsLeague', 'record:libertadores', 'record:leagueEngland', 'record:leagueSpain', 'record:leagueItaly', 'record:leagueGermany', 'record:ballonStreak', 'record:leagueStreak', 'record:primaryStreak', 'record:seasonAssists', 'record:seasonCleanSheets', 'record:leagueFrance', 'record:championsGames', 'title:league:liga-profesional', 'title:league:primera-nacional', 'title:league:liga-bolivia', 'title:league:copa-simon-bolivar', 'title:league:brasileirao', 'title:league:brasileirao-serie-b', 'title:league:liga-de-primera', 'title:league:primera-b', 'title:league:liga-dimayor', 'title:league:torneo-dimayor', 'title:league:ligapro-serie-a', 'title:league:ligapro-serie-b', 'title:league:premier-league', 'title:league:championship', 'title:league:laliga', 'title:league:laliga-2', 'title:league:ligue-1', 'title:league:ligue-2', 'title:league:bundesliga', 'title:league:2-bundesliga', 'title:league:serie-a', 'title:league:serie-b', 'title:league:liga-mx', 'title:league:copa-de-primera', 'title:league:division-intermedia', 'title:league:liga1', 'title:league:liga2', 'title:league:primeira-liga', 'title:league:liga-portugal-2', 'title:league:liga-uruguaya', 'title:league:segunda-division-uruguaya', 'title:league:usa-mls', 'title:league:liga-futve', 'title:league:liga-futve-2', 'title:cup:ARG', 'title:super:ARG', 'title:cup:BOL', 'title:cup:BRA', 'title:super:BRA', 'title:cup:CHI', 'title:super:CHI', 'title:cup:COL', 'title:super:COL', 'title:cup:ECU', 'title:super:ECU', 'title:cup:ENG', 'title:super:ENG', 'title:cup:ESP', 'title:super:ESP', 'title:cup:FRA', 'title:super:FRA', 'title:cup:GER', 'title:super:GER', 'title:cup:ITA', 'title:super:ITA', 'title:super:MEX', 'title:cup:PAR', 'title:super:PAR', 'title:cup:POR', 'title:super:POR', 'title:cup:URU', 